            "text": "{\"findings\":[{\"tipo\":\"GC\",\"causa_raiz\":\"Concatenação massiva de strings com operador '+' dentro de loop no Update(), alocando mais de 5MB por frame na memória gerenciada e provocando coletas frequentes do Garbage Collector com picos de travamento de até 15.96ms.\",\"codigo_refatorado\":\"using System;\\\\nusing System.Text;\\\\nusing UnityEngine;\\\\n\\\\nnamespace PerformanceAdvisor.StressTest\\\\n{\\\\n    public class StressTestScene : MonoBehaviour\\\\n    {\\\\n        public bool stressGc = false;\\\\n        public bool stressCpu = false;\\\\n        public bool stressDraw = false;\\\\n        public GameObject testPrefab;\\\\n        [Range(1, 20)] public float spawnRadius = 10f;\\\\n        [Range(1, 50)] public int cubesPerFrame = 1;\\\\n        public bool useUniqueMaterials = false;\\\\n        [Range(1, 512)] public int cpuScansPerFrame = 1;\\\\n        public int emptyObjects = 0;\\\\n        public int gcConcatIterations = 1000;\\\\n        public int gcArrayAllocs = 0;\\\\n        public int overdrawLayers = 0;\\\\n        public Material overdrawMaterial;\\\\n        [Range(0, 2000)] public int prepopulateCount = 0;\\\\n\\\\n        private StringBuilder _stringBuilder;\\\\n        private MaterialPropertyBlock _propBlock;\\\\n        private static readonly int ColorProperty = Shader.PropertyToID(\\\"_Color\\\");\\\\n\\\\n        private void Awake()\\\\n        {\\\\n            _stringBuilder = new StringBuilder(4096);\\\\n            _propBlock = new MaterialPropertyBlock();\\\\n        }\\\\n\\\\n        private void Start()\\\\n        {\\\\n            if (prepopulateCount \u003e 0 && testPrefab != null)\\\\n            {\\\\n                for (int i = 0; i \u003c prepopulateCount; i++)\\\\n                {\\\\n                    SpawnOne();\\\\n                }\\\\n            }\\\\n\\\\n            for (int i = 0; i \u003c emptyObjects; i++)\\\\n            {\\\\n                new GameObject(\\\"Empty_\\\" + i);\\\\n            }\\\\n\\\\n            if (overdrawLayers \u003e 0 && overdrawMaterial != null)\\\\n            {\\\\n                BuildOverdrawLayers();\\\\n            }\\\\n        }\\\\n\\\\n        private void BuildOverdrawLayers()\\\\n        {\\\\n            Camera cam = Camera.main;\\\\n            if (cam == null) return;\\\\n            float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad;\\\\n            for (int i = 0; i \u003c overdrawLayers; i++)\\\\n            {\\\\n                float d = cam.nearClipPlane + 0.05f + i * 0.001f;\\\\n                float h = 2f * d * Mathf.Tan(halfFov) * 1.1f;\\\\n                var quad = GameObject.CreatePrimitive(PrimitiveType.Quad);\\\\n                var col = quad.GetComponent\u003cCollider\u003e();\\\\n                if (col != null) Destroy(col);\\\\n                quad.name = \\\"Overdraw_\\\" + i;\\\\n                quad.transform.SetParent(cam.transform, false);\\\\n                quad.transform.localPosition = new Vector3(0f, 0f, d);\\\\n                quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f);\\\\n                quad.GetComponent\u003cRenderer\u003e().sharedMaterial = overdrawMaterial;\\\\n            }\\\\n        }\\\\n\\\\n        private void Update()\\\\n        {\\\\n            if (stressGc)\\\\n            {\\\\n                _stringBuilder.Clear();\\\\n                for (int i = 0; i \u003c gcConcatIterations; i++)\\\\n                {\\\\n                    _stringBuilder.Append(i);\\\\n                }\\\\n            }\\\\n\\\\n            if (stressDraw && testPrefab != null)\\\\n            {\\\\n                int n = Mathf.Max(1, cubesPerFrame);\\\\n                for (int i = 0; i \u003c n; i++) SpawnOne();\\\\n            }\\\\n        }\\\\n\\\\n        private void SpawnOne()\\\\n        {\\\\n            var clone = Instantiate(testPrefab, UnityEngine.Random.insideUnitSphere * spawnRadius, Quaternion.identity);\\\\n            if (useUniqueMaterials)\\\\n            {\\\\n                var rend = clone.GetComponent\u003cRenderer\u003e();\\\\n                if (rend != null)\\\\n                {\\\\n                    rend.GetPropertyBlock(_propBlock);\\\\n                    _propBlock.SetColor(ColorProperty, new Color(UnityEngine.Random.value, UnityEngine.Random.value, UnityEngine.Random.value));\\\\n                    rend.SetPropertyBlock(_propBlock);\\\\n                }\\\\n            }\\\\n        }\\\\n    }\\\\n}\\\",\\\"explicacao_didatica\\\":\\\"Strings em C# são imutáveis. Cada vez que usamos '+' para juntar texto, o computador cria uma cópia nova na memória RAM e descarta a antiga. Fazer isso centenas de vezes a cada frame cria uma montanha de lixo digital. Quando a memória se esgota, o Garbage Collector pausa o jogo inteiro para limpar a sujeira, causando travadas bruscas (stuttering). O uso de StringBuilder ou a remoção dessas criações desnecessárias mantém a taxa de quadros estável.\\\"},{\"    \n      ,\"explicacao_didatica\":\"Buscar todos os objetos de uma cena em tempo real a cada quadro é como ler uma lista telefônica inteira toda vez que você quer ligar para um amigo. Isso gasta quase todo o tempo que a CPU tinha para processar a lógica do jogo (62.36ms de 16.7ms disponíveis). O ideal é registrar os objetos em listas no início ou quando forem criados, evitando buscas globais repetitivas.\"}],\"dicas_level_design\":null}",
